def match(orders):
    import heapq

    buy_heap = []   # (-price, seq, id) - max price first, then earliest seq
    sell_heap = []  # (price, seq, id) - min price first, then earliest seq
    order_info = {}  # id -> {'side', 'price', 'qty', 'seq'}
    trades = []
    seq = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in order_info:
                del order_info[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        remaining = qty
        seq += 1
        cur_seq = seq

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]

                if top_id not in order_info:
                    heapq.heappop(sell_heap)
                    continue

                info = order_info[top_id]
                if info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    del order_info[top_id]
                    continue

                if typ != 'market' and price is not None and top_price > price:
                    break

                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty

                if info['qty'] == 0:
                    heapq.heappop(sell_heap)
                    del order_info[top_id]

            if typ == 'limit' and remaining > 0:
                order_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': cur_seq}
                heapq.heappush(buy_heap, (-price, cur_seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price

                if top_id not in order_info:
                    heapq.heappop(buy_heap)
                    continue

                info = order_info[top_id]
                if info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    del order_info[top_id]
                    continue

                if typ != 'market' and price is not None and top_price < price:
                    break

                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty

                if info['qty'] == 0:
                    heapq.heappop(buy_heap)
                    del order_info[top_id]

            if typ == 'limit' and remaining > 0:
                order_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': cur_seq}
                heapq.heappush(sell_heap, (price, cur_seq, oid))

    return trades

